{"role":"claude","entry":{"code":"#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\"\"\"\nrgon_safe_watcher.py\n────────────────────────────────────────────────────────────────────\n개인 대시보드 개발용 '투명한' 로컬 태스크 러너 (Python 3 표준 라이브러리 전용)\n\n  1) chrome_omni_commander 폴더의 .js/.json 파일을 읽기 전용으로 스캔해서\n     로컬 서버(127.0.0.1 / localhost) 포트와 URL 경로를 출력\n  2) 127.0.0.1 전용 HTTP 서버: 확장프로그램이 POST한 텍스트를\n     ahn_inbox_latest.txt에 저장하고 클립보드에 복사한 뒤 {\"ok\": true} 응답\n     (받은 내용은 절대 실행하지 않음)\n  3) Downloads\\\\omni_*.py → shin-agent 폴더로 이동한 뒤,\n     MessageBoxW(MB_TOPMOST)로 물어보고 사용자가 [예]를 누를 때만\n     RGON_Run.bat을 새 콘솔 창에서 실행\n  4) 포그라운드 콘솔 루프 (백그라운드 은폐, 레지스트리, 작업 스케줄러 등록 없음)\n     종료: 이 콘솔 창에서 Ctrl+C\n\n실행: python rgon_safe_watcher.py [--port 8765] [--no-server]\n\"\"\"\n\nimport argparse\nimport ctypes\nimport json\nimport os\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport threading\nimport time\nfrom collections import Counter\nfrom datetime import datetime\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom pathlib import Path\n\n# ──────────────────────────────── 설정 ────────────────────────────────\nBASE_DIR      = Path(r\"C:\\Users\\sangi\\Downloads\\shin-agent\")\nEXT_DIR       = BASE_DIR / \"chrome_omni_commander\"\nDOWNLOADS_DIR = Path(r\"C:\\Users\\sangi\\Downloads\")\nINBOX_FILE    = BASE_DIR / \"ahn_inbox_latest.txt\"\nRUN_BAT       = BASE_DIR / \"RGON_Run.bat\"\n\nBIND_HOST      = \"127.0.0.1\"          # 루프백 전용 (외부 네트워크 노출 없음)\nDEFAULT_PORT   = 8765                 # 확장프로그램에서 포트를 못 찾았을 때 사용\nMAX_BODY_BYTES = 5 * 1024 * 1024      # POST 본문 최대 5MB\nPOLL_SEC       = 2.0                  # 다운로드 폴더 확인 주기\nSCAN_EXTS      = {\".js\", \".json\"}\nSKIP_DIRS      = {\"node_modules\", \".git\", \"__pycache__\"}\nMAX_SCAN_FILE  = 5 * 1024 * 1024      # 너무 큰 파일은 스캔 생략\n\nIS_WINDOWS = os.name == \"nt\"\n\n# MessageBox 상수\nMB_YESNO         = 0x00000004\nMB_ICONQUESTION  = 0x00000020\nMB_DEFBUTTON2    = 0x00000100   # 기본 버튼 = [아니오] (Enter 실수로 실행되는 것 방지)\nMB_SETFOREGROUND = 0x00010000\nMB_TOPMOST       = 0x00040000\nIDYES            = 6\n\n_print_lock = threading.Lock()\n_file_lock = threading.Lock()\n\n\n# ──────────────────────────────── 공통 유틸 ────────────────────────────────\ndef log(tag: str, msg: str) -> None:\n    ts = datetime.now().strftime(\"%H:%M:%S\")\n    with _print_lock:\n        print(f\"[{ts}] [{tag:<6}] {msg}\", flush=True)\n\n\ndef fmt_size(n: int) -> str:\n    for unit in (\"B\", \"KB\", \"MB\", \"GB\"):\n        if n < 1024 or unit == \"GB\":\n            return f\"{n:.0f} {unit}\" if unit == \"B\" else f\"{n:.1f} {unit}\"\n        n /= 1024\n    return f\"{n} B\"\n\n\ndef line(char: str = \"─\", width: int = 72) -> None:\n    with _print_lock:\n        print(char * width, flush=True)\n\n\n# ──────────────────── 1) 확장프로그램 로컬 통신 설정 진단 (읽기 전용) ────────────────────\nLOCAL_URL_RE = re.compile(\n    r\"\"\"(?:https?|wss?)://(?:127\\.0\\.0\\.1|localhost)(?::(\\d{2,5}))?(/[^\\s'\"`<>)\\]},;]*)?\"\"\",\n    re.IGNORECASE,\n)\n# BASE_URL + \"/save\" 처럼 경로가 따로 떨어져 있는 경우를 위한 추정용 패턴\nPATH_LITERAL_RE = re.compile(r\"\"\"[\"'`](/[A-Za-z][A-Za-z0-9_\\-]*(?:/[A-Za-z0-9_\\-]+)*)[\"'`]\"\"\")\nPORT_ASSIGN_RE = re.compile(r\"\"\"\\bport\\b\\s*[:=]\\s*[\"']?(\\d{2,5})\\b\"\"\", re.IGNORECASE)\n\n\ndef scan_extension(ext_dir: Path) -> dict:\n    \"\"\".js/.json 파일을 읽기만 함. 아무것도 수정하지 않음.\"\"\"\n    result = {\n        \"ports\": Counter(),          # URL에서 확인된 포트\n        \"guessed_ports\": Counter(),  # port = 1234 형태의 추정 포트\n        \"paths\": Counter(),          # URL에서 확인된 경로\n        \"guessed_paths\": Counter(),  # 문자열 리터럴로 추정한 경로\n        \"hits\": [],                  # (상대경로, 줄번호, URL)\n        \"files_scanned\": 0,\n    }\n    if not extCopy","lang":"python","kind":"code","lines":106,"bytes":4657,"funcs":["log","fmt_size","line","scan_extension"],"funcCount":4,"tryCount":0,"hasEntry":false,"score":15,"blockCount":2,"hash":"722421153","ts":1792675931453,"url":"https://www.genspark.ai/agents?id=c724ec80-c357-41c0-9f57-27fde01c0cff","title":"Windows 로컬 태스크 러너 및 Chrome 확장 프로그램 진단 스크립트 작성 요청","role":"claude"}}